20	)
21	
22	// searchRow is one line of the level 1 table: an image, and the label of the
23	// registry that returned it.
24	type searchRow struct {
25		img   imagesearch.Image
26		label string
27		// ref is the full reference (host/repo), what the footer describes.
28		ref string
29	}
30	
31	// searchRowReference returns the full reference of an image found in the
32	// registry at registryURL: the host, then the final repository path. Docker
33	// Hub is always written docker.io, whichever spelling it is configured under.
34	func searchRowReference(registryURL string, img imagesearch.Image) string {
35		host := oci.RegistryHost(registryURL)
36		if host == "" {
37			return img.Repo
38		}
39		if oci.IsDockerHub(registryURL) {
40			host = "docker.io"
41		}
42		return host + "/" + img.Repo
43	}
44	
45	// searchColumns describes the level 1 table. Stars, Official and Description
46	// leave whole when the terminal narrows, in that reverse order (Description,
47	// Stars, Official), through Optional and DropFirst: drop() takes the rightmost
48	// DropFirst column first, then the rightmost Optional one.
49	func searchColumns() []datatable.Column[searchRow] {
50		return []datatable.Column[searchRow]{
51			datatable.IndicatorColumn(
52				func(searchRow) indicator.State { return indicator.Idle },
53				func(searchRow) string { return theme.IconDocker },
54				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
55			),
56			{
57				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
58				Cell:   func(r searchRow) string { return r.img.Name },
59				Search: func(r searchRow) string { return r.img.Name },
60			},
61			{
62				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
63				Cell: func(r searchRow) string { return r.label },
64			},
65			{
66				Title: "Stars", Sizing: datatable.SizingFixed, Optional: true, DropFirst: true, MinWidth: 6,
67				Cell: func(r searchRow) string {
68					if !r.img.HasStars {
69						return ""
70					}
71					return strconv.Itoa(r.img.Stars)
72				},
73			},
74			{
75				Title: "Official", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10,
76				Cell: func(r searchRow) string {
77					if r.img.Official {
78						return "official"
79					}
80					return ""
81				},
82			},
83			{
84				Title: "Description", Sizing: datatable.SizingContent, Optional: true, DropFirst: true,
85				MinWidth: 20, Flex: 2,
86				Cell:   func(r searchRow) string { return r.img.Description },
87				Search: func(r searchRow) string { return r.img.Description },
88			},
89		}
90	}
91	
92	// newSearchTable builds the level 1 table; rebuildSearchTable orders its rows.
93	func newSearchTable() *datatable.Model[searchRow] {
94		t := datatable.New(datatable.Config[searchRow]{
95			Columns:    searchColumns(),
96			SortColumn: -1,
97		})
98		return &t
99	}
100	
101	// rebuildSearchTable hands the collected images to the table.
102	func (b *RegistryBrowser) rebuildSearchTable() {
103		rows := make([]searchRow, len(b.images))
104		for i, img := range b.images {
105			label, ref := "", img.Repo
106			if e := b.entryFor(img.EntryKey); e != nil {
107				label = entryAlias(*e)
108				if label == "" {
109					label = e.URL
110				}
111				ref = searchRowReference(e.URL, img)
112			}
113			rows[i] = searchRow{img: img, label: label, ref: ref}
114		}
115		sortSearchRows(b.searchQuery, rows)
116		// The cursor follows the selected row by (EntryKey, Repo), not by index:
117		// rows of another registry land before or after it. Nothing selected (an
118		// empty table, so also a new search) goes to the first row, because an
119		// empty table keeps its old cursor index; a vanished row stays put.
120		prev, hadSel := b.searchTable.Selected()
121		b.searchTable.SetItems(rows)
122		if !hadSel {
123			b.searchTable.GotoTop()
124		} else {
125			for i, r := range b.searchTable.Visible() {
126				if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
127					b.searchTable.SetCursor(i)
128					break
129				}
130			}
131		}
132		b.resizeTables()
133	}
134	
135	// AddImageResults takes one registry's answer. It returns false, touching
136	// nothing, when the answer belongs to another lot. pendingSearches never goes
137	// below zero.
138	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
139		if msg.Gen != b.gen {
140			return false
141		}
142		if b.pendingSearches > 0 {
143			b.pendingSearches--
144		}
145		if msg.Err == nil {
146			for _, img := range msg.Images {
147				img.EntryKey = msg.EntryKey
148				b.images = append(b.images, img)
149			}
150		}
151		b.rebuildSearchTable()
152		return true
153	}
154	
155	// handleImagesKeyMsg handles the keys of the level 1 table. esc acts in
156	// order: the filter bar while it is open, then a confirmed query, then it
157	// cancels the lot and goes back to the form (which keeps the typed name and
158	// the selection). The lot's late answers are no longer wanted and are dropped
159	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
160	// nothing: a row has no action yet; → opens the row's tags.
161	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
162		if b.searchTable.InEditMode() {
163			return b, b.searchTable.Update(msg)
164		}
165		switch msg.String() {
166		case "right":
167			return b.openSelectedImageTags()
168		case "esc":
169			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
170				bar.ClearSearch()
171				b.searchTable.SetItems(b.searchTable.Items())
172				return b, nil
173			}
174			b.cancelInFlight()
175			b.gen = nextBrowserGen()
176			b.pendingSearches = 0
177			b.state = browserStateInput
178			b.searchTable.Blur()
179			b.updateFocus()
180			return b, nil
181		case "enter":
182			return b, nil
183		}
184		return b, b.searchTable.Update(msg)
185	}
186	
187	// handleImageSearchResult records one registry's answer; a stale one is ignored.
188	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
189		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
190			return m, nil
191		}
192		if msg.Err != nil {
193			alias := msg.EntryKey
194			if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
195				alias = entryAlias(*e)
196			}
197			if errors.Is(msg.Err, imagesearch.ErrUnsupported) {
198				log.Printf("INFO [oci_resources] image search on %s: %s", alias, msg.Err)
199				return m, nil
200			}
201			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(msg.Err))
202		}
203		return m, nil
204	}
205	
206	// searchErrorCause is the loggable text of a search error. A *url.Error holds
207	// the full request URL, which carries the text the user typed, so only its Op
208	// and Err are kept.
209	func searchErrorCause(err error) string {
210		var ue *url.Error
211		if errors.As(err, &ue) {
212			return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
213		}
214		return jobs.SafeCause(err)
215	}
216	
217	// handleRegistryBrowserWarn shows the browser's warning in the footer.
218	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
219		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
220	}
221	
222	// tagsLoadFailedText is the footer text of a failed tag listing opened by →.
223	const tagsLoadFailedText = "Could not load tags"
224	
225	// selectedImage returns the level 1 row under the cursor with its registry
226	// entry; false when there is no row or the entry is no longer known.
227	func (b *RegistryBrowser) selectedImage() (searchRow, *browserRegistryEntry, bool) {
228		row, ok := b.searchTable.Selected()
229		if !ok {
230			return searchRow{}, nil, false
231		}
232		entry := b.entryFor(row.img.EntryKey)
233		return row, entry, entry != nil
234	}
235	
236	// imageDrillIn reports whether → has an image to open: a row under the cursor
237	// whose registry entry is still known. One computation for the header and the
238	// handler (Rule 130).
239	func (b *RegistryBrowser) imageDrillIn() shortcut.Availability {
240		if _, _, ok := b.selectedImage(); !ok {
241			return shortcut.Unavailable(reasonNoImage)
242		}
243		return shortcut.Availability{}
244	}
245	
246	// openSelectedImageTags lists the tags of the selected level 1 row, on that
247	// row's registry only, with the row's final repository as is (no prefix, no
248	// library/ added again). Without a row it changes nothing and warns. A level 1
249	// search still running is cancelled: the browser has one lot at a time.
250	func (b *RegistryBrowser) openSelectedImageTags() (*RegistryBrowser, tea.Cmd) {
251		if av := b.imageDrillIn(); !av.Enabled() {
252			reason := av.Reason
253			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: reason} }
254		}
255		row, entry, _ := b.selectedImage()
256		b, cmd := b.startTagRequests([]tagRequest{b.newTagRequest(*entry, row.img.Repo)}, true)
257		b.tagsImage = row.img.Name
258		return b, cmd
259	}
